import net.neoforged.neoforge.capabilities.ItemCapability;

// Define a capability for items
ItemCapability<MyData> CAPABILITY = ItemCapability.create(
    () -> MyData.CODEC,
    () -> MyData.NONE
);

// Query from item stack
MyData data = stack.get(CAPABILITY).orElse(MyData.NONE);

// Modify data
stack.modify(CAPABILITY, data -> data.setValue(5));
